def calc(expr: str) -> int | str:
    n = len(expr)
    pos = 0

    def skip_spaces() -> None:
        nonlocal pos
        while pos < n and expr[pos].isspace():
            pos += 1

    def parse_add() -> int:
        nonlocal pos
        val = parse_mul()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in "+-":
                op = expr[pos]
                pos += 1
                rhs = parse_mul()
                if op == "+":
                    val += rhs
                else:
                    val -= rhs
            else:
                return val

    def parse_mul() -> int:
        nonlocal pos
        val = parse_unary()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in "*/%":
                op = expr[pos]
                pos += 1
                rhs = parse_unary()
                if op == "*":
                    val *= rhs
                elif op == "/":
                    if rhs == 0:
                        raise ZeroDivisionError
                    q = abs(val) // abs(rhs)
                    val = -q if (val < 0) ^ (rhs < 0) else q
                else:
                    if rhs == 0:
                        raise ZeroDivisionError
                    r = abs(val) % abs(rhs)
                    val = -r if val < 0 else r
            else:
                return val

    def parse_unary() -> int:
        nonlocal pos
        items: list[tuple[bool, int]] = []
        while True:
            neg = False
            while True:
                skip_spaces()
                if pos < n and expr[pos] == "-":
                    pos += 1
                    neg = not neg
                else:
                    break
            val = parse_primary()
            items.append((neg, val))
            skip_spaces()
            if pos < n and expr[pos] == "^":
                pos += 1
            else:
                break

        res = items[-1][1]
        if items[-1][0]:
            res = -res
        for i in range(len(items) - 2, -1, -1):
            neg, base = items[i]
            if res < 0:
                raise ValueError
            res = base ** res
            if neg:
                res = -res
        return res

    def parse_primary() -> int:
        nonlocal pos
        skip_spaces()
        if expr[pos] == "(":
            pos += 1
            val = parse_add()
            skip_spaces()
            pos += 1
            return val
        start = pos
        while pos < n and expr[pos].isdigit():
            pos += 1
        return int(expr[start:pos])

    try:
        return parse_add()
    except (ZeroDivisionError, ValueError):
        return "error"
